<script setup lang="ts">
import { posterSvgDataUri } from '../../utils/posterSvg'
import { computed, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useRouter } from 'vue-router'
import { hotelApi } from '../../api'
import { errorMessage } from '../../api/client'
import StatusTag from '../../components/StatusTag.vue'
import DateHeatmap from '../../components/DateHeatmap.vue'
import type { TravelProduct } from '../../types'

const router = useRouter(); const items = ref<TravelProduct[]>([]); const loading = ref(false); const status = ref(''); const selectedDate = ref(''); const viewMode = ref<'cards' | 'list'>('cards'); const preview = ref<TravelProduct | null>(null); const previewVisible = ref(false); const marketingLoading = ref(false)
const visibleItems = computed(() => selectedDate.value ? items.value.filter((item) => item.target_date === selectedDate.value) : items.value)
async function load() { loading.value = true; try { items.value = (await hotelApi.products(status.value || undefined)).data.items } catch (e) { ElMessage.error(errorMessage(e)) } finally { loading.value = false } }
async function remove(row: TravelProduct) { try { await ElMessageBox.confirm(`确定删除“${row.product_name}”吗？已有预约意向的产品会安全归档。`, '删除产品', { type: 'warning' }); const response = await hotelApi.deleteProduct(row.id); ElMessage.success(response.data.message); await load() } catch (e) { if (e !== 'cancel' && e !== 'close') ElMessage.error(errorMessage(e)) } }
function poster(row: TravelProduct) { return row.marketing_assets?.find(asset => asset.asset_type === 'POSTER') }
function openPreview(row: TravelProduct) { preview.value = row; previewVisible.value = true }
async function regenerate(row: TravelProduct) { marketingLoading.value = true; try { const updated = (await hotelApi.regenerateMarketing(row.id, { style: 'SEEDING', generate_image: true })).data; const index = items.value.findIndex(item => item.id === row.id); if (index >= 0) items.value[index] = updated; preview.value = updated; ElMessage.success('已生成新的旅行者文案、SVG 海报与产品专属主图') } catch (e) { ElMessage.error(errorMessage(e)) } finally { marketingLoading.value = false } }
onMounted(load)
</script>

<template>
  <div class="page-head"><div><div class="eyebrow">产品池</div><h1>当前产品池</h1><p>按日期查看待发布、在售和库存紧张的产品；可在详情中编辑内容与生成宣传素材。</p></div><div class="header-actions"><el-radio-group v-model="viewMode" class="view-mode-switch" size="small" aria-label="产品展示方式"><el-radio-button label="cards">卡片</el-radio-button><el-radio-button label="list">列表</el-radio-button></el-radio-group><el-button plain @click="load">刷新</el-button><el-button type="primary" @click="router.push('/hotel/products/generate')">＋ 生成新方案</el-button></div></div>
  <div class="panel filter-bar"><div><el-radio-group v-model="status" @change="load"><el-radio-button label="">全部</el-radio-button><el-radio-button label="DRAFT">草稿</el-radio-button><el-radio-button label="ON_SALE">在售</el-radio-button><el-radio-button label="LOW_STOCK">库存紧张</el-radio-button><el-radio-button label="PAUSED">已暂停</el-radio-button></el-radio-group><DateHeatmap v-model="selectedDate" :items="items" date-key="target_date" quantity-key="sale_quantity" label="出发日期" /></div></div>
  <div v-if="viewMode === 'cards'" class="product-pool-grid"><article v-for="row in visibleItems" :key="row.id" class="pool-card panel"><div class="pool-card__visual" @click="openPreview(row)"><img v-if="poster(row)?.poster_svg" :src="posterSvgDataUri(poster(row)?.poster_svg)" :alt="poster(row)?.title || row.product_name" /><img v-else-if="poster(row)?.image_url" :src="poster(row)?.image_url" :alt="poster(row)?.title || row.product_name" /><div v-else class="pool-card__placeholder"><span>杭州旅居</span><strong>{{ row.marketing_title }}</strong></div><span class="visual-hint">查看宣传素材</span></div><div class="pool-card__body"><div class="product-card__top"><span class="eyebrow">{{ row.theme }} · {{ row.target_date }}</span><StatusTag :status="row.status" /></div><h2>{{ row.product_name }}</h2><p class="pool-card__copy">{{ row.marketing_content }}</p><div class="product-card__resources"><span v-for="resource in row.resources.slice(0, 3)" :key="resource.id">{{ resource.resource_name }}</span></div><div class="pool-card__metrics"><div><small>可售</small><strong>{{ row.sale_quantity }} 套</strong></div><div><small>售价</small><strong>¥{{ row.suggested_price }}</strong></div><div><small>毛利率</small><strong>{{ (Number(row.gross_margin) * 100).toFixed(1) }}%</strong></div></div><div class="pool-card__actions"><el-button plain @click="openPreview(row)">素材预览</el-button><el-button link type="primary" @click="router.push(`/hotel/products/${row.id}`)">详情</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></div></div></article></div>
  <div v-else class="panel table-wrap"><el-table v-loading="loading" :data="visibleItems" style="width:100%" @row-click="openPreview"><el-table-column prop="product_name" label="产品" min-width="250"><template #default="{row}"><strong>{{ row.product_name }}</strong><div class="muted">{{ row.theme }} · {{ row.target_date }}</div></template></el-table-column><el-table-column label="状态" width="105"><template #default="{row}"><StatusTag :status="row.status" /></template></el-table-column><el-table-column label="可售" width="85"><template #default="{row}">{{ row.sale_quantity }} 套</template></el-table-column><el-table-column label="售价" width="100"><template #default="{row}">¥{{ row.suggested_price }}</template></el-table-column><el-table-column label="素材" width="100"><template #default="{row}"><span :class="poster(row)?.image_url ? 'success-text' : 'muted'">{{ poster(row)?.image_url ? 'AI 主图' : 'SVG 海报' }}</span></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click.stop="openPreview(row)">预览</el-button><el-button link type="primary" @click.stop="router.push(`/hotel/products/${row.id}`)">编辑</el-button><el-button link type="danger" @click.stop="remove(row)">删除</el-button></template></el-table-column></el-table></div>
  <div v-if="!loading && !visibleItems.length" class="panel empty-state">这一天暂无产品；可切换日期，或生成一组新方案。</div>

  <el-dialog v-if="preview" v-model="previewVisible" title="宣传素材工作台" width="980px" top="4vh"><div class="marketing-workbench"><div class="workbench-poster"><img v-if="poster(preview)?.poster_svg" :src="posterSvgDataUri(poster(preview)?.poster_svg)" :alt="poster(preview)?.title || preview.product_name" /><img v-else-if="poster(preview)?.image_url" :src="poster(preview)?.image_url" :alt="poster(preview)?.title || preview.product_name" /><div class="poster-caption">{{ preview.product_name }} · {{ preview.target_date }} · {{ preview.weather }}</div></div><div class="workbench-copy"><div class="workbench-title"><div><div class="eyebrow">宣传内容</div><h2>{{ preview.marketing_title }}</h2></div><el-button type="primary" plain :loading="marketingLoading" @click="regenerate(preview)">生成主图与文案</el-button></div><div v-for="asset in preview.marketing_assets.filter(item => item.asset_type !== 'POSTER')" :key="asset.asset_type" class="copy-card"><div class="product-card__top"><strong>{{ asset.title }}</strong><el-tag size="small" effect="plain">{{ asset.platform }}</el-tag></div><p>{{ asset.content }}</p><small>{{ asset.visual_brief }}</small><b>{{ asset.call_to_action }}</b></div></div></div><template #footer><el-button @click="router.push(`/hotel/products/${preview.id}`)">进入产品详情</el-button><el-button type="primary" @click="previewVisible = false">关闭</el-button></template></el-dialog>
</template>

<style scoped>
