h:0}.workbench-title{display:flex;justify-content:space-between;gap:12px;align-items:start;margin-bottom:12px}.workbench-title h2{font-size:21px;margin:7px 0 0}.copy-card{padding:14px;border:1px solid var(--line);border-radius:12px;background:#fbfdfc;margin-top:10px}.copy-card p{white-space:pre-wrap;line-height:1.75;font-size:13px;margin:10px 0}.copy-card small{display:block;color:var(--muted);line-height:1.6}.copy-card b{display:block;color:var(--teal);font-size:12px;margin-top:8px}@media(max-width:850px){.product-pool-grid,.marketing-workbench{grid-template-columns:1fr}}

/* Stable SVG image rendering */
