.workbench-poster>img{height:auto}.pool-card__body{padding:18px}.pool-card__copy{font-size:14px;line-height:1.7}
.filter-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}.product-pool-grid{grid-template-columns:repeat(auto-fill,minmax(245px,1fr));gap:12px}.pool-card__visual{height:150px}.pool-card__body{padding:13px}.pool-card__body h2{overflow:hidden;margin:9px 0 6px;font-size:16px;text-overflow:ellipsis;white-space:nowrap}.pool-card__copy{min-height:38px;font-size:11px;line-height:1.55}.pool-card__metrics{gap:5px;margin:11px 0}.pool-card__metrics div{padding:8px;background:var(--panel-soft);border-radius:8px}.pool-card__metrics small{font-size:9px}.pool-card__metrics strong{font-family:var(--font-mono);font-size:12px}.visual-hint{right:10px;bottom:10px;padding:5px 8px;font-size:10px}.success-text{color:#40665b;font-size:11px;font-weight:600}@media(max-width:700px){.filter-bar{align-items:stretch;flex-direction:column}.product-pool-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.pool-card__visual{height:105px}.pool-card__body{padding:10px}.pool-card__metrics{grid-template-columns:1fr 1fr}.pool-card__metrics div:last-child{display:none}}

/* The image is a thumbnail, not a background for operational information. */
.header-actions{display:flex;align-items:center;justify-content:flex-end;gap:10px;flex-wrap:wrap}.view-mode-switch{order:-1}.filter-bar{display:block;padding:10px 12px}.filter-bar>div{display:grid;gap:9px}.filter-bar :deep(.date-heatmap){border:0;padding:0;background:transparent}.product-pool-grid{grid-template-columns:repeat(auto-fill,minmax(390px,1fr));gap:10px}.pool-card{display:grid;grid-template-columns:124px minmax(0,1fr);min-height:176px}.pool-card__visual{height:auto;min-height:176px}.pool-card__visual>img{height:100%;object-fit:cover}.pool-card__body{min-width:0;padding:12px}.pool-card__body h2{margin:7px 0 4px;font-size:15px}.pool-card__copy{min-height:32px;margin:0;font-size:11px;line-height:1.48}.pool-card .product-card__resources{max-height:43px;margin:8px 0;overflow:hidden}.pool-card .product-card__resources span{font-size:9px}.pool-card__metrics{margin:8px 0;gap:5px}.pool-card__metrics div{padding:6px 7px}.pool-card__metrics strong{font-size:11px}.visual-hint{right:7px;bottom:7px;padding:4px 6px;background:rgba(31,34,32,.78);font-size:9px}.pool-card__actions{gap:3px}.pool-card__actions :deep(.el-button){min-height:27px;padding:5px 7px;font-size:10px}@media(max-width:700px){.page-head .header-actions{justify-content:flex-start;margin-top:12px}.filter-bar{padding:10px}.product-pool-grid{grid-template-columns:1fr}.pool-card{grid-template-columns:100px minmax(0,1fr);min-height:142px}.pool-card__visual{min-height:142px}.pool-card__body{padding:10px}.pool-card__metrics{margin:7px 0}.pool-card__metrics div{padding:5px}.pool-card__metrics div:last-child{display:block}.pool-card .product-card__resources{display:none}}
</style>
